{"title": "Do both reservoir samplers give every item the same chance?", "question": "Does each implementation include every stream position with probability k/n?", "claim": {"statement": "Algorithm R includes every item with probability exactly k/n.", "source": "paper", "evidence_quote": "every item has probability exactly k/n of being in the reservoir"}, "factor": "Which implementation draws the replacement index", "explanations": [{"id": "E1", "statement": "Both implementations are uniform; group B's lower early estimates are noise.", "expected": [{"metric": "first_k_ratio", "left": "impl_b", "relation": "equal", "right": "impl_a", "tolerance": 0.05}]}, {"id": "E2", "statement": "impl_b draws j from {0..i-1}, so the first k items are evicted too often and under-represented.", "expected": [{"metric": "first_k_ratio", "left": "impl_b", "relation": "less", "right": "impl_a", "tolerance": 0.05}]}], "bet": "E2", "conditions": [{"id": "impl_a", "label": "Group A", "description": "impl_a/reservoir.py, j uniform over {0..i}"}, {"id": "impl_b", "label": "Group B", "description": "impl_b/reservoir.py, j uniform over {0..i-1}"}], "metrics": [{"id": "first_k_ratio", "label": "First-k inclusion ratio", "unit": "x expected", "description": "Inclusion frequency of the first k stream items divided by k/n (1.0 = uniform)."}, {"id": "rest_ratio", "label": "Remaining-items inclusion ratio", "unit": "x expected", "description": "Same ratio for items k..n-1."}], "seeds": [1, 2, 3, 4, 5], "implementation_note": "Calls each uploaded reservoir_sample on range(100) with k=5, 2,000 times per seed, using the same random stream for both.", "harness_code": "import counterlab_sandbox as sb

IMPLEMENTATIONS = {"impl_a": "impl_a/reservoir.py", "impl_b": "impl_b/reservoir.py"}
N, K, TRIALS = 100, 5, 2000


def measure(condition, seed):
    module = sb.load(IMPLEMENTATIONS[condition])
    rng = sb.rng(seed)
    counts = [0] * N
    for _ in range(TRIALS):
        for item in module.reservoir_sample(range(N), K, rng=rng):
            counts[item] += 1
    expected = TRIALS * K / N
    return {"first_k_ratio": sum(counts[:K]) / (K * expected),
            "rest_ratio": sum(counts[K:]) / ((N - K) * expected)}
"}
